contracts/CrossChainRouter.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity 0.8.7;

import "./DForceDexRouter.sol";
import "./lib/RouterEvent.sol";
import "./interface/IWETH.sol";
import { IMessageBus, IBridge } from "./interface/ICeler.sol";
import "@openzeppelin/contracts-upgradeable/utils/cryptography/draft-EIP712Upgradeable.sol";

contract CrossChainRouter is DForceDexRouter, RouterEvent, EIP712Upgradeable {
    using Address for address;
    using SafeERC20 for IERC20;

    event SetMBusSupport(address _old, address _new);
    event SetSignAddress(address _old, address _new);
    event SetFeeRecipient(address _old, address _new);

    bytes32 private constant CROSS_FEE_HASH = keccak256("CrossFee(address token,uint256 amount,uint256 deadline)");

    address public immutable wGasToken;
    address public mBusSupport;

    address public signAddress;
    address public feeRecipient;

    function reinitialize() public reinitializer(2) {
        __EIP712_init("Cross swap router", "1");
    }

    constructor(address _wGasToken) DForceDexRouter() {
        reinitialize();
        wGasToken = _wGasToken;
    }

    modifier onlyMessageBus() {
        require(msg.sender == messageBus(), "CrossChainRouter: caller is not message bus");
        _;
    }

    function messageBus() public view returns (address) {
        return IMBusSupport(mBusSupport).messageBus();
    }

    function cbridge() public view returns (address) {
        return IMessageBus(messageBus()).liquidityBridge();
    }

    ///@param _first Whether to swap first
    function crossChainSwap(
        SwapBaseInfo memory _baseInfo,
        CrossParams memory _crossParams,
        uint64 _dstChainId,
        address _dstContract,
        address _crossToken,
        uint32 _maxSlippage,
        bool _first,
        SwapInfo memory _swapInfo
    ) external payable returns (bytes32 _transferId) {
        if (_baseInfo._from == ETH) {
            require(msg.value >= _baseInfo._amount, "CrossChainRouter: msg.value not enough");
        } else {
            IERC20(_baseInfo._from).safeTransferFrom(msg.sender, address(this), _baseInfo._amount);
        }

        if (_first) {
            _baseInfo._amount = this._blendSwap(_baseInfo, _swapInfo);
            _safeApprove(IERC20(_crossToken), cbridge(), _baseInfo._amount);
            // slippage * 1M, eg. 0.5% -> 5000
            IBridge(cbridge()).send(msg.sender, _crossToken, _baseInfo._amount, _dstChainId, _crossParams._cbridgeNonce, _crossParams._cbridgeMaxSlippage);
        } else {
            require(_crossParams._deadline > block.timestamp, "CrossChainRouter: Cross fee verification time expired");
            require(_verifyCrossFee(_crossParams._token, _crossParams._amount, _crossParams._deadline, _crossParams._signature), "CrossChainRouter: Cross fee verification failed");
            bytes memory _returns = mBusSupport.functionDelegateCall(
                abi.encodeWithSelector(IMBusSupport._crossChainSwap.selector, _baseInfo, _crossParams._amount, _dstChainId, _dstContract, _crossToken, _maxSlippage, !_first, _swapInfo)
            );
            _transferId = abi.decode(_returns, (bytes32));
        }
    }

    function getMBusFee(
        SwapBaseInfo memory _baseInfo,
        CrossParams memory _crossParams,
        bool _first,
        SwapInfo memory _swapInfo
    ) external view returns (uint256 _fee) {
        bytes memory _returns = mBusSupport.functionStaticCall(abi.encodeWithSelector(IMBusSupport.getFee.selector, _baseInfo, _crossParams._amount, !_first, _swapInfo));
        (, _fee) = abi.decode(_returns, (bytes, uint256));
    }

    function executeMessageWithTransfer(
        address, //Send cross chain contracts
        address _token,
        uint256 _amount,
        uint64, //_srcChainId, Source chain number
        bytes calldata _message, //send data
        address //_executor
    ) external payable onlyMessageBus returns (ExecutionStatus) {
        _warpGasToken(_token, _amount);
        CrossChainData memory _data = abi.decode(_message, (CrossChainData));
        _amount -= _data._crossFee;
        if (_data._swap) {
            _data._baseInfo._from = _token;
            _data._baseInfo._amount = _amount;
            uint256 _returns = this._blendSwap(_data._baseInfo, _data._swapInfo);
            ///@dev If _baseInfo._to is gasToken, it will be replaced with wtoken when it is passed in
            _transfer(_data._receiver, _data._baseInfo._to, _returns);
            emit CrossSwap(_data._receiver, _token, _data._baseInfo._to, _amount, _returns);
        } else {
            _transfer(_data._receiver, _token, _amount);
            emit OnlyReceive(_data._baseInfo._to, _token, _amount);
        }
        _transfer(feeRecipient, _token, _data._crossFee);
        return ExecutionStatus.Success;
    }

    //Bridge error call this
    function executeMessageWithTransferRefund(
        address _token,
        uint256 _amount,
        bytes calldata _message,
        address //_executor
    ) external payable onlyMessageBus returns (ExecutionStatus) {
        _warpGasToken(_token, _amount);
        CrossChainData memory _data = abi.decode(_message, (CrossChainData));
        _amount -= _data._crossFee;
        address _refund = _transfer(_data._receiver, _token, _amount);
        emit TransferRefund(_data._receiver, _refund, _amount);
        _transfer(feeRecipient, _token, _data._crossFee);
        return ExecutionStatus.Success;
    }

    //Target Chain Transaction error call this
    function executeMessageWithTransferFallback(
        address, //_sender
        address _token,
        uint256 _amount,
        uint64, //_srcChainId
        bytes memory _message,
        address //_executor
    ) external payable onlyMessageBus returns (ExecutionStatus) {
        _warpGasToken(_token, _amount);
        CrossChainData memory _data = abi.decode(_message, (CrossChainData));
        _amount -= _data._crossFee;
        address _refund = _transfer(_data._receiver, _token, _amount);
        emit TransferFallback(_data._receiver, _refund, _amount);
        _transfer(feeRecipient, _token, _data._crossFee);
        return ExecutionStatus.Success;
    }

    function setMBusSupport(address _new) external onlyOwner {
        address _old = mBusSupport;
        mBusSupport = _new;
        emit SetMBusSupport(_old, _new);
    }

    function setFeeRecipient(address _new) external onlyOwner {
        address _old = feeRecipient;
        feeRecipient = _new;
        emit SetFeeRecipient(_old, _new);
    }

    function setSignAddress(address _new) external onlyOwner {
        address _old = signAddress;
        signAddress = _new;
        emit SetSignAddress(_old, _new);
    }

    function _transfer(
        address _receiver,
        address _token,
        uint256 _amount
    ) private returns (address) {
        if (_token == ETH) {
            payable(_receiver).transfer(_amount);
            return ETH;
        } else {
            IERC20(_token).safeTransfer(_receiver, _amount);
            return _token;
        }
    }

    function ownerTransfer(
        address _token,
        address _to,
        uint256 _amount
    ) public onlyOwner {
        IERC20(_token).safeTransfer(_to, _amount);
    }

    function ownerTransferETH(address _to, uint256 _amount) public onlyOwner {
        payable(_to).transfer(_amount);
    }

    function _warpGasToken(address _token, uint256 _amount) internal {
        if (_token == wGasToken) IWETH(wGasToken).deposit{ value: _amount }();
    }

    function _verifyCrossFee(
        address _token,
        uint256 _amount,
        uint256 _deadline,
        bytes memory _signature
    ) internal view returns (bool) {
        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(CROSS_FEE_HASH, _token, _amount, _deadline)));
        return signAddress == ECDSAUpgradeable.recover(digest, _signature);
    }
}

contracts/DForceDexRouter.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity 0.8.7;

import "./lib/Structs.sol";
import "./lib/OneinchSupport.sol";
import "./interface/IMBusSupport.sol";
import "./interface/I1inchSupport.sol";
import "./interface/IProtocolSupport.sol";
import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";

contract DForceDexRouter is ReentrancyGuardUpgradeable, BaseSupport, OwnableUpgradeable, Structs {
    using Address for address;

    struct SwapPoolInfo {
        uint8 _poolType;
        bytes _data;
    }

    struct InchInfo {
        address _from;
        uint256 _amount;
        bool _order;
        bytes _data;
    }

    modifier onlyThis() {
        require(msg.sender == address(this), "DForceDexRouter: this func only this contract call");
        _;
    }

    uint8 public constant SWAP_TYPE_DEFAULT = 1;
    uint8 public constant SWAP_TYPE_1INCH = 2;

    event Set1inchSupport(address _old, address _new);
    event AddSupport(uint8 _type, address _support);
    event Swap(address _sender, address _from, uint256 _fromAmount, address _to, uint256 _toAmount);
    event SwapPoolType(uint8 _type);

    address public inchSupport;
    mapping(uint8 => address) public support;

    function initialize() public initializer {
        __Ownable_init();
        __ReentrancyGuard_init();
    }

    constructor() {
        initialize();
    }

    function quote(uint8 _type, bytes memory _data) external returns (uint256, bytes memory) {
        address _support = support[_type];
        require(_support != address(0), "DForceDexRouter: not have this type");
        bytes memory _returns = _support.functionDelegateCall(abi.encodeWithSelector(IProtocolSupport.quote.selector, _data));
        return abi.decode(_returns, (uint256, bytes));
    }

    function tokensQuote(uint8 _type, bytes memory _data) external returns (uint256, bytes memory) {
        address _support = support[_type];
        require(_support != address(0), "DForceDexRouter: not have this type");
        bytes memory _returns = _support.functionDelegateCall(abi.encodeWithSelector(IProtocolSupport.tokensQuote.selector, _data));
        return abi.decode(_returns, (uint256, bytes));
    }

    function swap(
        SwapBaseInfo memory _baseInfo,
        SwapPoolInfo[] memory _swaps,
        InchInfo memory _1inchInfo
    ) external payable nonReentrant returns (uint256) {
        uint256 _amount = _baseInfo._amount;
        if (_baseInfo._from == ETH) {
            require(msg.value >= _baseInfo._amount, "DForceDexRouter: msg.value not enough");
        } else {
            SafeERC20.safeTransferFrom(IERC20(_baseInfo._from), msg.sender, address(this), _amount);
        }

        _amount = this._swap(_baseInfo, _swaps, _1inchInfo);

        if (_baseInfo._to == ETH) {
            payable(msg.sender).transfer(_amount);
        } else {
            SafeERC20.safeTransfer(IERC20(_baseInfo._to), msg.sender, _amount);
        }

        emit Swap(msg.sender, _baseInfo._from, _baseInfo._amount, _baseInfo._to, _amount);
        return _amount;
    }

    function _blendSwap(SwapBaseInfo memory _baseInfo, SwapInfo memory _swapInfo) external payable onlyThis returns (uint256 _returns) {
        if (_swapInfo._swapType == SWAP_TYPE_DEFAULT) {
            (SwapPoolInfo[] memory _swaps, InchInfo memory _1inchInfo) = abi.decode(_swapInfo._swapData, (SwapPoolInfo[], InchInfo));
            _returns = this._swap(_baseInfo, _swaps, _1inchInfo);
        } else if (_swapInfo._swapType == SWAP_TYPE_1INCH) {
            InchInfo memory _1inchInfo = abi.decode(_swapInfo._swapData, (InchInfo));
            if (_1inchInfo._amount != _baseInfo._amount) {
                _1inchInfo._data = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.modifyOneinchAmount.selector, _1inchInfo._data, _baseInfo._amount));
                _1inchInfo._data = abi.decode(_1inchInfo._data, (bytes));
            }
            bytes memory _data = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.inchSwapNoHandle.selector, _baseInfo._from, _baseInfo._amount, _1inchInfo._data));
            _returns = abi.decode(_data, (uint256));
            require(_returns >= _baseInfo._minReturn, string(abi.encodePacked("DForceDexRouter: _returns < _minReturn, returns: ", Strings.toString(_returns))));
        } else {
            require(false, "DForceDexRouter: wrong _swapType");
        }
    }

    function _swap(
        SwapBaseInfo memory _baseInfo,
        SwapPoolInfo[] memory _swaps,
        InchInfo memory _1inchInfo
    ) external payable onlyThis returns (uint256 _amount) {
        _amount = _baseInfo._amount;
        if (_1inchInfo._data.length != 0 && _1inchInfo._order) {
            bytes memory _data = _1inchInfo._data;
            if (_1inchInfo._amount != _amount) {
                _data = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.modifyOneinchAmount.selector, _1inchInfo._data, _amount));
                _data = abi.decode(_data, (bytes));
            }
            bytes memory _returns = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.inchSwapNoHandle.selector, _1inchInfo._from, _amount, _data));
            _amount = abi.decode(_returns, (uint256));
        }

        _amount = _internalSwap(_swaps, _amount);

        if (_1inchInfo._data.length != 0 && !_1inchInfo._order) {
            bytes memory _data = _1inchInfo._data;
            if (_1inchInfo._amount != _amount) {
                _data = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.modifyOneinchAmount.selector, _1inchInfo._data, _amount));
                _data = abi.decode(_data, (bytes));
            }
            bytes memory _returns = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.inchSwapNoHandle.selector, _1inchInfo._from, _amount, _data));
            _amount = abi.decode(_returns, (uint256));
        }

        require(_amount >= _baseInfo._minReturn, string(abi.encodePacked("DForceDexRouter: _returns < _minReturn, returns: ", Strings.toString(_amount))));
    }

    function inchSwap(
        address _from,
        address _to,
        uint256 _amount,
        uint256 _minReturn,
        bytes memory _inData
    ) external payable returns (uint256 _returns) {
        bytes memory _data = inchSupport.functionDelegateCall(abi.encodeWithSelector(I1inchSupport.inchSwap.selector, _from, _to, _amount, _minReturn, _inData));
        _returns = abi.decode(_data, (uint256));
        emit Swap(msg.sender, _from, _amount, _to, _returns);
    }

    function set1inchSupport(address _new) external onlyOwner {
        address _old = inchSupport;
        inchSupport = _new;
        emit Set1inchSupport(_old, _new);
    }

    function addSupport(uint8 _type, address _support) external onlyOwner {
        support[_type] = _support;
        emit AddSupport(_type, _support);
    }

    function uniswapV3SwapCallback(
        int256,
        int256,
        bytes memory _data
    ) external {
        support[UNI3_TYPE].functionDelegateCall(abi.encodeWithSelector(DForceDexRouter.uniswapV3SwapCallback.selector, 0, 0, _data));
    }

    function _internalSwap(SwapPoolInfo[] memory _swaps, uint256 _amount) internal returns (uint256) {
        for (uint256 i = 0; i < _swaps.length; i++) {
            address _support = support[_swaps[i]._poolType];
            if (_support == address(0)) continue;
            bytes memory _returns = _support.functionDelegateCall(abi.encodeWithSelector(IProtocolSupport.swap.selector, _amount, _swaps[i]._data));
            _amount = abi.decode(_returns, (uint256));
        }
        return _amount;
    }
}

contracts/interface/I1inchSupport.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity 0.8.7;

interface I1inchSupport {
    function modifyOneinchAmount(bytes memory _data, uint256 _amount) external pure returns (bytes memory);

    function inchSwapNoHandle(
        address _from,
        uint256 _amount,
        bytes memory _inData
    ) external payable returns (uint256);

    function inchSwap(
        address _from,
        address _to,
        uint256 _amount,
        uint256 _minReturn,
        bytes memory _inData
    ) external payable returns (uint256 _returns);
}

